-- =============================================================================
-- Projects: homes, offices and other spaces the business has furnished.
--
-- Entered by the owner with their own photos. Nothing is generated by the
-- site. Only published projects are visible to visitors.
-- Photos live in the public product-images bucket under projects/.
-- =============================================================================

create table public.projects (
  id             uuid primary key default gen_random_uuid(),
  title          text        not null check (char_length(btrim(title)) between 2 and 120),
  slug           text        not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 120),
  space_type     text        check (space_type is null or char_length(space_type) <= 60),
  location       text        check (location is null or char_length(location) <= 120),
  completed_on   date,
  summary        text        check (summary is null or char_length(summary) <= 400),
  body           text        check (body is null or char_length(body) <= 8000),
  scope          text[]      not null default '{}' check (cardinality(scope) <= 30),
  cover_image_url text       check (cover_image_url is null or cover_image_url ~ '^https://'),
  gallery        text[]      not null default '{}' check (cardinality(gallery) <= 40),
  is_published   boolean     not null default false,
  sort_order     integer     not null default 0,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

-- Every gallery link must be https (same rule as the cover).
create or replace function public.projects_check_gallery()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if exists (select 1 from unnest(new.gallery) u where u !~ '^https://' or char_length(u) > 1000) then
    raise exception using errcode = '23514', message = 'Gallery images must be https links.';
  end if;
  return new;
end;
$$;

create trigger projects_check_gallery
  before insert or update on public.projects
  for each row execute function public.projects_check_gallery();

create index projects_published_idx on public.projects (is_published, sort_order);

create trigger projects_set_updated_at
  before update on public.projects
  for each row execute function public.set_updated_at();

alter table public.projects enable row level security;

revoke all on public.projects from anon, authenticated;
grant select on public.projects to anon;
grant select, insert, update, delete on public.projects to authenticated;

create policy "projects: public read published"
  on public.projects for select to anon
  using (is_published);

create policy "projects: read published or admin"
  on public.projects for select to authenticated
  using (is_published or (select public.is_admin()));

create policy "projects: admin insert"
  on public.projects for insert to authenticated
  with check ((select public.is_admin()));

create policy "projects: admin update"
  on public.projects for update to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));

create policy "projects: admin delete"
  on public.projects for delete to authenticated
  using ((select public.is_admin()));

-- Allow reordering projects from the admin.
create or replace function public.admin_set_sort_order(p_table text, p_ids uuid[])
returns void
language plpgsql
set search_path = ''
as $$
begin
  perform public.assert_admin();
  if p_table not in ('categories', 'hero_slides', 'product_images', 'product_options', 'product_variants', 'delivery_zones', 'reviews', 'projects') then
    raise exception using errcode = 'P0001', message = 'INVALID_TABLE';
  end if;
  execute format(
    'update public.%I t set sort_order = x.pos from unnest($1) with ordinality as x(id, pos) where t.id = x.id',
    p_table
  ) using p_ids;
end;
$$;
